contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 strike, uint256 premium, uint256 duration, uint256 expiration, uint256 nonce) public {
        address[] memory emptyAddrs = new address[](0);
        C.ERC20Asset[] memory noErc20 = new C.ERC20Asset[](0);
        C.ERC721Asset[] memory noErc721 = new C.ERC721Asset[](0);

        C.Order memory order = C.Order({
            maker: address(this),
            isCall: true,
            isLong: true,
            baseAsset: address(c),
            strike: strike,
            premium: premium,
            duration: duration,
            expiration: expiration,
            nonce: nonce,
            whitelist: emptyAddrs,
            floorTokens: emptyAddrs,
            erc20Assets: noErc20,
            erc721Assets: noErc721
        });

        bytes32 orderHash = c.hashOrder(order);
        c.cancel(order);
        bool cancelled = c.cancelledOrders(orderHash);

        // A different caller than the maker must not be able to cancel
        C.Order memory otherOrder = C.Order({
            maker: address(0xdead),
            isCall: true,
            isLong: true,
            baseAsset: address(c),
            strike: strike,
            premium: premium,
            duration: duration,
            expiration: expiration,
            nonce: nonce,
            whitelist: emptyAddrs,
            floorTokens: emptyAddrs,
            erc20Assets: noErc20,
            erc721Assets: noErc721
        });
        bool reverted;
        try c.cancel(otherOrder) { reverted = false; } catch { reverted = true; }

        assert(cancelled && !c.cancelledOrders(c.hashOrder(otherOrder)) && reverted);
    }
    receive() external payable {}
}

