    constructor(C _c) { c = _c; }

    function run(bool amMaker) public {
        C.Order memory order;
        order.maker = amMaker ? address(this) : address(0xbeef);
        order.isCall = true;
        order.isLong = false;
        order.strike = 1 ether;
        order.premium = 0.01 ether;
        order.duration = 3 days;
        order.expiration = block.timestamp + 1 days;
        order.nonce = 42;

        bytes32 h = c.hashOrder(order);

        bool reverted;
        if (amMaker) {
            c.cancel(order);
            reverted = false;
        } else {
            try c.cancel(order) { reverted = false; } catch { reverted = true; }
        }

        bool cancelled = c.cancelledOrders(h);

        assert(
            (amMaker && !reverted && cancelled) ||
            (!amMaker && reverted && !cancelled)
        );
    }
}

