    constructor(C _c) { c = _c; }

    function run(
        address maker,
        bool isCall,
        address baseAsset,
        uint256 strike,
        uint256 premium,
        uint256 duration,
        uint256 expiration,
        uint256 nonce
    ) public {
        require(maker != address(0), "pre");
        require(duration < 10_000 days, "pre");

        address[] memory empty = new address[](0);
        C.ERC20Asset[] memory e20 = new C.ERC20Asset[](0);
        C.ERC721Asset[] memory e721 = new C.ERC721Asset[](0);

        C.Order memory original = C.Order({
            maker: maker,
            isCall: isCall,
            isLong: true,
            baseAsset: baseAsset,
            strike: strike,
            premium: premium,
            duration: duration,
            expiration: expiration,
            nonce: nonce,
            whitelist: empty,
            floorTokens: empty,
            erc20Assets: e20,
            erc721Assets: e721
        });

        C.Order memory flipped = C.Order({
            maker: maker,
            isCall: isCall,
            isLong: false,
            baseAsset: baseAsset,
            strike: strike,
            premium: premium,
            duration: duration,
            expiration: expiration,
            nonce: nonce,
            whitelist: empty,
            floorTokens: empty,
            erc20Assets: e20,
            erc721Assets: e721
        });

        bytes32 h1 = c.hashOppositeOrder(original);
        bytes32 h2 = c.hashOrder(flipped);
        bytes32 h3 = c.hashOppositeOrder(flipped);
        bytes32 h4 = c.hashOrder(original);

        assert(h1 == h2 && h3 == h4);
    }

    receive() external payable {}
}

