contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address maker, bool isCall, bool isLong, address baseAsset) public {
        C.Order memory order;
        order.maker = maker;
        order.isCall = isCall;
        order.isLong = isLong;
        order.baseAsset = baseAsset;

        bool reverted;
        if (maker == address(this)) {
            c.cancel(order);
            reverted = false;
        } else {
            try c.cancel(order) { reverted = false; } catch { reverted = true; }
        }

        bytes32 orderHash = c.hashOrder(order);
        bool cancelled = c.cancelledOrders(orderHash);

        assert((maker == address(this)) ? (!reverted && cancelled) : (reverted && !cancelled));
    }

    receive() external payable {}
}

