            nonce: nonce,
            whitelist: whitelist,
            floorTokens: floorTokens,
            erc20Assets: erc20Assets,
            erc721Assets: erc721Assets
        });

        // different order, same fields but different nonce
        C.Order memory other = C.Order({
            maker: address(this),
            isCall: true,
            isLong: true,
            baseAsset: baseAsset,
            strike: strike,
            premium: premium,
            duration: duration,
            expiration: expiration,
