            whitelist: whitelist,
            floorTokens: floorTokens,
            erc20Assets: erc20Assets,
            erc721Assets: erc721Assets
        });

        bytes32 h = c.hashOrder(order);
        require(!c.cancelledOrders(h), "pre: already cancelled");
        require(!c.cancelledOrders(c.hashOrder(other)), "pre: already cancelled other");

        bool reverted;
        try c.cancel(order) { reverted = false; } catch { reverted = true; }

        assert(
            !reverted
            && c.cancelledOrders(h)
            && !c.cancelledOrders(c.hashOrder(other))
        );
    }

    receive() external payable {}
}

