    function run(uint256 newFee, uint256 valueSent) public payable {
        require(valueSent == 0 || address(this).balance >= valueSent);
        bool reverted;
        uint256 beforeFee = c.fee();
        if (valueSent > 0) {
            try c.setFee{value: valueSent}(newFee) { reverted = false; } catch { reverted = true; }
        } else {
            try c.setFee(newFee) { reverted = false; } catch { reverted = true; }
        }
        if (newFee < 30) {
            assert(!reverted && c.fee() == newFee);
        } else {
            assert(reverted && c.fee() == beforeFee);
        }
    }
    receive() external payable {}
}

