contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(
        bool isCall,
        bool isLong,
        address baseAsset,
        uint256 strike,
        uint256 premium,
        uint256 duration,
        uint256 expiration,
        uint256 nonce
    ) public {
        require(baseAsset != address(0));
        C.Order memory order = C.Order({
            maker: address(this),
            isCall: isCall,
            isLong: isLong,
            baseAsset: baseAsset,
            strike: strike,
            premium: premium,
            duration: duration,
            expiration: expiration,
            nonce: nonce,
            whitelist: new address[](0),
            floorTokens: new address[](0),
            erc20Assets: new C.ERC20Asset[](0),
            erc721Assets: new C.ERC721Asset[](0)
        });
        bytes32 h = c.hashOrder(order);
        require(!c.cancelledOrders(h));
        c.cancel(order);
        assert(c.cancelledOrders(h) && c.cancelledOrders(c.hashOrder(order)));
    }
    receive() external payable {}
}
